echo "=== GGUFs no path canônico ===" && ls -la "/mnt/dados/Assistente Pessoal/modelos LLM/" 2>/dev/null; echo; echo "=== metadados GGUF (n_ctx_train) ===" && for f in "/mnt/dados/Assistente Pessoal/modelos LLM/"/*.gguf; do [ -f "$f" ] && printf "%-55s " "$(basename "$f")" && python3 - "$f" <<'PY'
import sys,struct
f=sys.argv[1]
sz=0
with open(f,'rb') as fh:
    while True:
        h=fh.read(8)
        if not h: break
        key=h[:4].decode('latin1'); szt=struct.unpack('<I',h[4:8])[0]
        data=fh.read(szt)
        if key=='name':
            try: nm=data.decode('utf-8','replace')
            except: nm=data.decode('latin1','replace')
        elif key=='n_ctx_train':
            try: ctx=int.from_bytes(data,'little'); print(f'{nm[:40]:40} ctx={ctx}')
            except: pass
        elif key=='general.architecture':
            try: arch=data.decode('utf-8','replace'); print(f'{nm[:40]:40} arch={arch}')
            except: pass
PY
done 2>/dev/null

